package com.bank.constraints.model;

import java.math.BigDecimal;

public class Account {
    private final String id;
    private final String holderName;   // NOT NULL
    private final String email;        // UNIQUE (nullable)
    private String status;             // DEFAULT 'ACTIVE'
    private BigDecimal balance;        // CHECK >= 0

    public Account(String id, String holderName, String email, String status, BigDecimal balance) {
            this.id = id;
            this.holderName = holderName
            this.email = email;
        this.status = status; this.balance = balance;
    }
    public String getId() { return id; }
    public String getHolderName() { return holderName; }
    public String getEmail() { return email; }
    public String getStatus() { return status; }
    public BigDecimal getBalance() { return balance; }
}
