package com.bank.constraints.db;

import com.bank.constraints.model.Account;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// Enforces every constraint type on write, like a real database would.
public class ConstraintedStore {
    private static final Logger log = Logger.getLogger(ConstraintedStore.class.getName());
    private final Map<String, Account> accounts = new HashMap<>();   // PRIMARY KEY space
    private final Set<String> emails = new HashSet<>();              // UNIQUE space

    public void insertAccount(Account a) {
        // PRIMARY KEY: id must be unique and present
        if (a.getId() == null) throw new IllegalArgumentException("PRIMARY KEY null");
        if (accounts.containsKey(a.getId())) throw new IllegalStateException("PRIMARY KEY duplicate: " + a.getId());
        // NOT NULL: holder name mandatory
        if (a.getHolderName() == null) throw new IllegalArgumentException("NOT NULL violated: holder_name");
        // UNIQUE: email (if present) must not duplicate
        if (a.getEmail() != null && !emails.add(a.getEmail())) throw new IllegalStateException("UNIQUE violated: " + a.getEmail());
        // DEFAULT: fill status if missing
            if (a.getStatus() == null) { a = withStatus(a, "ACTIVE");
            log.fine("DEFAULT status=ACTIVE applied"); }
        // CHECK: balance >= 0
        if (a.getBalance().compareTo(BigDecimal.ZERO) < 0) throw new IllegalStateException("CHECK violated: balance < 0");
        accounts.put(a.getId(), a);
        final Account stored = a;
        log.info(() -> "account inserted: " + stored.getId() + " status=" + stored.getStatus());
    }

    public void insertTransaction(String accountId, BigDecimal amount) {
        // FOREIGN KEY: account must exist
        if (!accounts.containsKey(accountId)) throw new IllegalStateException("FOREIGN KEY violated: no account " + accountId);
        // CHECK: amount > 0
        if (amount.compareTo(BigDecimal.ZERO) <= 0) throw new IllegalStateException("CHECK violated: amount <= 0");
        log.info(() -> "transaction inserted for " + accountId + " amount=" + amount);
    }

    private Account withStatus(Account a, String status) {
        return new Account(a.getId(), a.getHolderName(), a.getEmail(), status, a.getBalance());
    }
}
