package com.bank.constraints;

import com.bank.constraints.db.ConstraintedStore;
import com.bank.constraints.model.Account;
import java.math.BigDecimal;
import java.util.logging.*;

public class ConstraintsDemo {
    private static final Logger log = Logger.getLogger(ConstraintsDemo.class.getName());

    public static void main(String[] args) {
        setupLogger();
        ConstraintedStore db = new ConstraintedStore();

        tryWrite("valid account (DEFAULT status applied)",
            () -> db.insertAccount(new Account("SAV2001","Rajesh Kumar","rajesh@nbi.in", null, new BigDecimal("1000000"))));
        tryWrite("duplicate PRIMARY KEY",
            () -> db.insertAccount(new Account("SAV2001","Someone","x@nbi.in","ACTIVE", new BigDecimal("1"))));
        tryWrite("NOT NULL violated (no holder name)",
            () -> db.insertAccount(new Account("CUR3001", null,"priya@nbi.in","ACTIVE", new BigDecimal("250000"))));
        tryWrite("UNIQUE email violated",
            () -> db.insertAccount(new Account("CUR3001","Priya Sharma","rajesh@nbi.in","ACTIVE", new BigDecimal("250000"))));
        tryWrite("CHECK balance<0 violated",
            () -> db.insertAccount(new Account("LOA4001","Loan Acct","loan@nbi.in","ACTIVE", new BigDecimal("-5"))));
        tryWrite("valid transaction (FK ok)",
            () -> db.insertTransaction("SAV2001", new BigDecimal("50000")));
        tryWrite("FOREIGN KEY violated (no such account)",
            () -> db.insertTransaction("NOPE9999", new BigDecimal("50000")));
    }

    private static void tryWrite(String label, Runnable r) {
        try { r.run(); } catch (RuntimeException ex) { log.severe(label + " → REJECTED: " + ex.getMessage()); }
    }

    private static void setupLogger() {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
